import mermaid from 'mermaid';
import teleportIcons from "../../data/teleport-icons.json";

mermaid.registerIconPacks([
  // Custom icons loaded from src/mermaid-icons
  {
    name: teleportIcons.prefix,
    icons: teleportIcons,
  },
  // Subsets generated by scripts/prepare-files.mts containing only the icons
  // referenced in Mermaid diagrams: loaded on-demand
  // https://icones.js.org/collection/logos
  {
    name: "logos",
    loader: () => import("../../data/logos-icons.json").then((module) => module.default),
  },
  // https://icones.js.org/collection/carbon
  {
    name: "carbon",
    loader: () => import("../../data/carbon-icons.json").then((module) => module.default),
  },
]);
